package rw.isurafashion.service;
import rw.isurafashion.model.*; import rw.isurafashion.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class OrderService {
 final ShopService shop; final OrderRepository orders; final CartItemRepository cart; final ProductRepository products;
 public OrderService(ShopService s,OrderRepository o,CartItemRepository c,ProductRepository p){shop=s;orders=o;cart=c;products=p;}
 @Transactional public Order checkout(User u,String method,String paymentResult,String discountCode,String idem){if(idem!=null&&!idem.isBlank()){var old=orders.findByIdempotencyKeyAndCustomer(idem,u);if(old.isPresent())return old.get();}List<CartItem> items=cart.findByUser(u);if(items.isEmpty())throw new IllegalArgumentException("Your cart is empty");for(CartItem i:items)if(i.getProduct().getStockQty()<i.getQuantity())throw new IllegalArgumentException("Stock changed for "+i.getProduct().getName());long subtotal=items.stream().mapToLong(i->i.getQuantity()*(long)i.getProduct().getPriceRwf()).sum();long discount=0;if("ISURA2026".equalsIgnoreCase(discountCode))discount=Math.round(subtotal*0.10);int count=items.stream().mapToInt(CartItem::getQuantity).sum();if(count>=5)discount+=Math.round(subtotal*0.10);long after=Math.max(0,subtotal-discount);long shipping=(after>=50000||"GOLD".equalsIgnoreCase(u.getLoyaltyTier()))?0:2000;Order o=new Order();o.setOrderNo("ISF-"+UUID.randomUUID().toString().substring(0,8).toUpperCase());o.setCustomer(u);o.setSubtotal(subtotal);o.setDiscount(discount);o.setShipping(shipping);o.setTotal(after+shipping);o.setPaymentMethod(method);o.setIdempotencyKey(idem);for(CartItem i:items){OrderLine l=new OrderLine();l.setProduct(i.getProduct());l.setQuantity(i.getQuantity());l.setUnitPrice(i.getProduct().getPriceRwf());o.addLine(l);}String result=paymentResult==null?"SUCCESS":paymentResult.toUpperCase();if("TIMEOUT".equals(result))o.setState(Order.OrderState.PAYMENTTIMEDOUT);else if("DECLINE".equals(result))o.setState(Order.OrderState.CANCELLED);else{o.setState(Order.OrderState.PAID);o.setPaymentReference("PAY-"+UUID.randomUUID().toString().substring(0,10).toUpperCase());for(CartItem i:items){i.getProduct().setStockQty(i.getProduct().getStockQty()-i.getQuantity());products.save(i.getProduct());}cart.deleteAll(items);}return orders.save(o);}
 @Transactional public Order transition(User actor,Long id,String target,String tracking){Order o=orders.findById(id).orElseThrow();if(actor.getRole().equals("CUSTOMER")&&!o.getCustomer().getId().equals(actor.getId()))throw new SecurityException();Order.OrderState next=Order.OrderState.valueOf(target.toUpperCase());boolean legal=switch(o.getState()){case PLACED->next==Order.OrderState.PAID||next==Order.OrderState.CANCELLED||next==Order.OrderState.PAYMENTTIMEDOUT;case PAID->next==Order.OrderState.SHIPPED||next==Order.OrderState.CANCELLED;case SHIPPED->next==Order.OrderState.DELIVERED;default->false;};if(!legal)throw new IllegalStateException("Illegal order transition: "+o.getState()+" -> "+next);o.setState(next);if(next==Order.OrderState.SHIPPED){if(tracking==null||tracking.isBlank())throw new IllegalArgumentException("Tracking number is required");o.setTrackingNumber(tracking);}return orders.save(o);}
}
